style.css:
/* Midnight Violet — Roblox */

:root {
    /* Можешь менять эти цвета */
    --my-bg: #0b0712;
    --my-panel: #151020;
    --my-card: #1c142b;
    --my-accent: #8b35d6;
    --my-hover: #a855f7;
    --my-text: #eee6fa;
    --my-muted: #a99bbd;
    --my-border: #302044;
}

/* Основной фон */
body {
    background: var(--my-bg) !important;
    color: var(--my-text) !important;
}

/* Панели */
nav,
header,
section,
aside {
    border-color: var(--my-border) !important;
}

/* Карточки */
div[class*="card"],
div[class*="Card"] {
    border-radius: 12px !important;
}

/* Текст */
h1, h2, h3, p, span {
    color: var(--my-text);
}

/* Ссылки */
a {
    color: #c084fc !important;
}

/* Кнопки */
button {
    border-radius: 10px !important;
}

/* Выделение при наведении */
button:hover,
a:hover {
    filter: brightness(1.2) !important;
}

/* Поля ввода */
input,
textarea {
    background: var(--my-panel) !important;
    color: var(--my-text) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 9px !important;
}
